@observer
class Controls extends React.Component {
    path = "plugin_sheq_assist/employees/contracts/";

    @observable
    state = {
        index: 0
    };

    constructor() {
        super();

        this.onNext = this.onNext.bind(this);
        
        this.form = new Form();
    }

    //<editor-fold desc="onNext">
    onNext(e, btn) {
        const {form, isNewEmployee, refs: {contractDetailsTab, salaryInfoTab}} = this;
        const {idx} = btn.props;
        if(idx === 1) {
            if (!isNewEmployee && !form.isValid('employee')) {
                infoDialog.open('Employee is required');
                return;
            }
        }
        if(idx === 2) {
            const contract_details = toNoneNullObject(contractDetailsTab.form.data);
            if (contract_details) {
                if (contractDetailsTab.form.isValid('expiry_date') && !contractDetailsTab.form.isValid('start_date')) {
                    infoDialog.open('Start Date is required');
                    return;
                }

                if (contractDetailsTab.form.isValid('start_time') && !contractDetailsTab.form.isValid('end_time')) {
                    infoDialog.open('Working End Time is required');
                    return;
                }
                if (contractDetailsTab.form.isValid('end_time') && !contractDetailsTab.form.isValid('start_time')) {
                    infoDialog.open('Working Start Time is required');
                    return;
                }
            }
        }
        if(idx === 3) {
            const salary_info = toNoneNullObject(salaryInfoTab.form.data);
            if (salary_info) {//payment_type, 
                if (!salaryInfoTab.form.isValid('payment_type')) {
                    infoDialog.open('Payment Type is required');
                    return;
                }
                if (salaryInfoTab.form.get('payment_type') === 'Salary') {
                    if (!salaryInfoTab.form.isValid('salary_interval')) {
                        infoDialog.open('Salary Interval is required');
                        return;
                    }
                } else {//Wage
    //                if (!salaryInfoTab.form.isValid('wage')) {
    //                    infoDialog.open('Wage Type is required');
    //                    return;
    //                }
                }
            }
        }
        
        return true;
    }
    //</editor-fold>

    //<editor-fold desc="onSubmit">
    onSubmit(e, btn, onSaved) {
        const {form, isNewEmployee, refs: {contractDetailsTab, salaryInfoTab}} = this;

        if (!isNewEmployee && !form.isValid('employee')) {
            infoDialog.open('Employee is required');
            return;
        }
        
        const contract_details = toNoneNullObject(contractDetailsTab.form.data);
        if (contract_details) {
            if (contractDetailsTab.form.isValid('expiry_date') && !contractDetailsTab.form.isValid('start_date')) {
                infoDialog.open('Start Date is required');
                return;
            }
            
            if (contractDetailsTab.form.isValid('start_time') && !contractDetailsTab.form.isValid('end_time')) {
                infoDialog.open('Working End Time is required');
                return;
            }
            if (contractDetailsTab.form.isValid('end_time') && !contractDetailsTab.form.isValid('start_time')) {
                infoDialog.open('Working Start Time is required');
                return;
            }
        }
        const salary_info = toNoneNullObject(salaryInfoTab.form.data);
        if (salary_info) {//payment_type, 
            if (!salaryInfoTab.form.isValid('payment_type')) {
                infoDialog.open('Payment Type is required');
                return;
            }
            if (salaryInfoTab.form.get('payment_type') === 'Salary') {
                if (!salaryInfoTab.form.isValid('salary_interval')) {
                    infoDialog.open('Salary Interval is required');
                    return;
                }
            } else {//Wage
//                if (!salaryInfoTab.form.isValid('wage')) {
//                    infoDialog.open('Wage Type is required');
//                    return;
//                }
            }
        }

        console.log(form)
        const {
            employee,//
            doc,//
            job_profile_doc//
        } = form.data;

        let data = {};

        if (contract_details) {
            if (contractDetailsTab.form.isValid('start_date')) {
                contract_details.start_date = contract_details.start_date.getTime();
            }
            if (contractDetailsTab.form.isValid('expiry_date')) {
                contract_details.expiry_date = contract_details.expiry_date.getTime();
            }

            const {
                contract_type,
                start_date,
                expiry_date,
                end_of_trial_period,
                start_time,
                end_time,
                daily_working_hours,
                notes,
            } = contract_details;
            data.contract_details_list = {
                data: [{
                    contract_type,
                    start_date: Dates.formatTimestampSQL(start_date),
                    expiry_date: Dates.formatTimestampSQL(expiry_date),
                    end_of_trial_period: Dates.formatTimestampSQL(end_of_trial_period),
                    start_time,
                    end_time,
                    daily_working_hours,
                    notes,
                }]
            };
        }

        if (salary_info) {
            const {
                payment_type,
                salary_interval,
                salary,
                wage,
                deductible,//[{text, value}]
            } = salary_info;

            const deductible_list = deductible ? deductible.list.filter(v => !!v && !!v.text && !!v.value) : [];

            data.salary_info_list = {
                data: [{
                    payment_type,
                    salary_interval,
                    salary,
                    wage,
                    deductible_list: {data: deductible_list},//[{text, value}]
                }]
            };
        }

        if(isNewEmployee) {
            data = {
                ...data,
                employee,
                doc,
                job_profile_doc,
            };

            console.log("res", data)
            onSaved && onSaved(data);
            infoDialog.open("Record added.");
            infoDialog.close(2000);
            this.props.close();
            return;
        }

        data = {
            ...data,
            employee_id: employee.id,
            doc: doc && doc.path,
            job_profile_doc: job_profile_doc && job_profile_doc.path,
        };

        console.log(data)

        btn.text("Saving...").disabled();
        progressDialog.open();
        insertEmployeeContract(data).then(employee_res => {
            console.log("res", employee_res)
            onSaved && onSaved(employee_res);
            infoDialog.open("Record successfully saved.");
            infoDialog.close(2000);
            this.props.close();
        }).finally(() => {
            btn.text("Save").enabled();
            setTimeout(() => progressDialog.close());
        });
    }
    //</editor-fold>

    get isNewEmployee() {
        const {props: {dialog: {props: {isNewEmployee}}}} = this;
        return isNewEmployee;
    }

    get employeeItem() {
        return this.props.state.item;
    }

    //<editor-fold desc="render">
    render() {
        const {isNewEmployee, props: {onFormNext, onFormBack, onFormOpen}} = this;

        let idx = 1;
        return <FormControls>
            {!isNewEmployee && <Row
                rendered
                active
                idx={1}
                title={`${++idx}. Employee`}
                onFormOpen={onFormOpen}
                onFormNext={onFormNext}
            >
                <SelectEmployeeInput name="employee" placeholder="Employee..." defaultValue={this.employeeItem} className="col-lg-12 form-control" onChange={this.form.onChange}/>
            </Row>}
            <Row
                rendered
                active={isNewEmployee}
                idx={2}
                title={`${++idx}. Contract Details`}
                onFormOpen={onFormOpen}
                onFormBack={!isNewEmployee && onFormBack}
                onFormNext={onFormNext}
            >
                <ContractDetails ref="contractDetailsTab"/>
            </Row>
            <Row
                rendered
                idx={3}
                title={`${++idx}. Salary Information`}
                onFormOpen={onFormOpen}
                onFormBack={onFormBack}
                onFormNext={onFormNext}
            >
                <SalaryInfo ref="salaryInfoTab"/>
            </Row>
            <Row
                rendered
                idx={4}
                title={`${++idx}. Contract Document Attachment`}
                onFormOpen={onFormOpen}
                onFormBack={onFormBack}
                onFormNext={onFormNext}
            >
                <UploadButton
                    name="doc"
                    buttonTitle="Upload File (PDF, Word or Photo)"
                    type={['PDF', 'Word', 'Image']}
                    showOnlyIcon
                    className="col-lg-12"
                    onChange={this.form.onChange}
                />
            </Row>
            <Row
                rendered
                idx={5}
                title={`${++idx}. Job Profile Document Attachment`}
                onFormOpen={onFormOpen}
                onFormBack={onFormBack}
            >
                <UploadButton
                    name="job_profile_doc"
                    buttonTitle="Upload File (PDF, Word or Photo)"
                    type={['PDF', 'Word', 'Image']}
                    showOnlyIcon
                    className="col-lg-12"
                    onChange={this.form.onChange}
                />
            </Row>
        </FormControls>;
    }
    //</editor-fold>
}

